SELECT id, product_id, revenue, AVG(revenue) OVER (PARTITION BY MONTH(sale_date), product_id ORDER BY revenue, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS revenue_avg_5_prior, CORR(units, revenue) OVER (PARTITION BY store_id) AS corr_units_revenue, AVG(units) OVER (PARTITION BY MONTH(sale_date), product_id) AS sale_date_month_avg_units, LAG(units, 2) OVER (PARTITION BY store_id ORDER BY units, id) AS prev_units FROM store_sales;
